mapper.update:
UPDATE fnd31_opr_fund
   SET fnd31_fund_id          = #{r.fundId},
       fnd31_fund_advice_type = #{r.fundAdviceType},
       fnd31_price            = #{r.price},
       fnd31_qty              = #{r.qty},
       fnd31_cont_amt         = #{r.contAmt},
       fnd31_fee              = #{r.fee},
       fnd31_settle_amt       = #{r.settleAmt}
 WHERE fnd31_opr_fund_id = #{r.oprFundId}
   AND fnd31_opr_id      = #{r.oprId}

mapper.delete:
DELETE FROM fnd31_opr_fund
 WHERE fnd31_opr_id = #{oprId}
   AND fnd31_opr_fund_id IN
#{oprFundId}

mapper.select:
SELECT fnd01_fund_code_id
  FROM fnd01_fund_code
 WHERE fnd01_fund_cd    = #{fundCode}
   AND fnd01_company_id = #{companyId}
 LIMIT 1

SELECT adv02_account_id
  FROM adv02_account
 WHERE adv02_company_id = #{companyId}
   AND adv02_manage_cd  = #{manageCode}
 LIMIT 1

SELECT SUM(fnd31_qty)
  FROM fnd31_opr_fund
 WHERE fnd31_opr_id = #{oprId}

   AND fnd31_opr_fund_id != #{exceptFundId}
